#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

namespace {
constexpr std::uint32_t IM = 139968;
constexpr std::uint32_t IA = 3877;
constexpr std::uint32_t IC = 29573;
constexpr std::size_t WIDTH = 60;

std::uint32_t seed = 42;

struct Symbol {
    char character;
    double probability;
};

template <std::size_t K>
std::array<char, IM> make_lookup(const Symbol (&symbols)[K]) {
    std::array<double, K> cumulative{};
    double total = 0.0;
    for (std::size_t i = 0; i < K; ++i) {
        total += symbols[i].probability;
        cumulative[i] = total;
    }

    std::array<char, IM> lookup{};
    std::size_t symbol = 0;
    for (std::uint32_t state = 0; state < IM; ++state) {
        const double random = static_cast<double>(state) / IM;
        while (symbol + 1 < K && random >= cumulative[symbol]) {
            ++symbol;
        }
        lookup[state] = symbols[symbol].character;
    }
    return lookup;
}

void write_repeated(std::uint64_t length) {
    static constexpr char ALU[] =
        "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG"
        "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAG"
        "ACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAATACAAAA"
        "ATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGG"
        "AGGCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAG"
        "TGAGCCGAGATCGCGCCACTGCACTCCAGCCTGGGCGACAGAGCGAG"
        "ACTCCGTCTCAAAAA";

    constexpr std::size_t alu_length = sizeof(ALU) - 1;
    constexpr std::size_t block_bases = alu_length * WIDTH;

    // This block ends at both an ALU boundary and a line boundary.
    std::string block;
    block.reserve(block_bases + alu_length);
    std::size_t position = 0;
    for (std::size_t line = 0; line < alu_length; ++line) {
        for (std::size_t column = 0; column < WIDTH; ++column) {
            block.push_back(ALU[position]);
            if (++position == alu_length) {
                position = 0;
            }
        }
        block.push_back('\n');
    }

    while (length >= block_bases) {
        std::fwrite(block.data(), 1, block.size(), stdout);
        length -= block_bases;
    }

    if (length != 0) {
        const std::size_t remaining = static_cast<std::size_t>(length);
        std::fwrite(block.data(), 1, remaining + remaining / WIDTH, stdout);
        if (remaining % WIDTH != 0) {
            std::fputc('\n', stdout);
        }
    }
}

void write_random(std::uint64_t length,
                  const std::array<char, IM>& lookup) {
    constexpr std::size_t LINES_PER_BLOCK = 16384;
    static char buffer[LINES_PER_BLOCK * (WIDTH + 1)];

    std::uint32_t state = seed;
    std::uint64_t lines = length / WIDTH;

    while (lines != 0) {
        const std::size_t count = static_cast<std::size_t>(
            std::min<std::uint64_t>(lines, LINES_PER_BLOCK));

        char* output = buffer;
        for (std::size_t line = 0; line < count; ++line) {
            for (std::size_t column = 0; column < WIDTH; ++column) {
                state = (state * IA + IC) % IM;
                *output++ = lookup[state];
            }
            *output++ = '\n';
        }

        std::fwrite(buffer, 1, static_cast<std::size_t>(output - buffer),
                    stdout);
        lines -= count;
    }

    const std::size_t remaining = static_cast<std::size_t>(length % WIDTH);
    if (remaining != 0) {
        for (std::size_t i = 0; i < remaining; ++i) {
            state = (state * IA + IC) % IM;
            buffer[i] = lookup[state];
        }
        buffer[remaining] = '\n';
        std::fwrite(buffer, 1, remaining + 1, stdout);
    }

    seed = state;
}
} // namespace

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    char* end = nullptr;
    const std::uint64_t n = std::strtoull(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || n == 0 ||
        n > UINT64_MAX / 5) {
        return 1;
    }

    static constexpr Symbol IUB[] = {
        {'a', 0.27}, {'c', 0.12}, {'g', 0.12}, {'t', 0.27},
        {'B', 0.02}, {'D', 0.02}, {'H', 0.02}, {'K', 0.02},
        {'M', 0.02}, {'N', 0.02}, {'R', 0.02}, {'S', 0.02},
        {'V', 0.02}, {'W', 0.02}, {'Y', 0.02}
    };

    static constexpr Symbol HOMO_SAPIENS[] = {
        {'a', 0.3029549426680},
        {'c', 0.1979883004921},
        {'g', 0.1975473066391},
        {'t', 0.3015094502008}
    };

    static const auto iub_lookup = make_lookup(IUB);
    static const auto homo_lookup = make_lookup(HOMO_SAPIENS);

    std::fputs(">ONE Homo sapiens alu\n", stdout);
    write_repeated(2 * n);

    std::fputs(">TWO IUB ambiguity codes\n", stdout);
    write_random(3 * n, iub_lookup);

    std::fputs(">THREE Homo sapiens frequency\n", stdout);
    write_random(5 * n, homo_lookup);

    return std::fflush(stdout) == 0 ? 0 : 1;
}

